flowchart TD
  A["Recurrence T(n)"] --> B{"Has form T(n)=aT(n/b)+f(n)?"}
  B -- "No" --> X["Does not apply Master Theorem\nUse iteration, recursion tree, substitution, or characteristic equation"]
  B -- "Yes" --> C{"a ≥ 1 and b > 1?"}
  C -- "No" --> X
  C -- "Yes" --> D["Compute p = log_b(a)"]
  D --> E{"Compare f(n) with n^p"}
  E -- "f(n) ∈ O(n^(p-ε))" --> F["Case 1\nT(n)=Θ(n^p)"]
  E -- "f(n) ∈ Θ(n^p)" --> G["Case 2\nT(n)=Θ(n^p log n)"]
  E -- "f(n) ∈ Ω(n^(p+ε))" --> H{"Regularity?\na f(n/b) ≤ c f(n), 0<c<1"}
  H -- "Yes" --> I["Case 3\nT(n)=Θ(f(n))"]
  H -- "No" --> X
  E -- "Between cases / no ε" --> X
